123	enum PinnedEventsBannerState: Equatable {
124	    case loading(numbersOfEvents: Int)
125	    case loaded(state: PinnedEventsState)
126	    
127	    var isEmpty: Bool {
128	        switch self {
129	        case .loaded(let state):
130	            return state.pinnedEventContents.isEmpty
131	        case .loading(let numberOfEvents):
132	            return numberOfEvents == 0
133	        }
134	    }
135	    
136	    var isLoading: Bool {
137	        switch self {
138	        case .loading:
139	            return true
140	        default:
141	            return false
142	        }
143	    }
144	    
145	    var selectedPinnedEventID: String? {
146	        switch self {
147	        case .loaded(let state):
148	            return state.selectedPinnedEventID
149	        default:
150	            return nil
151	        }
152	    }
153	    
154	    var count: Int {
155	        switch self {
156	        case .loaded(let state):
157	            return state.pinnedEventContents.count
158	        case .loading(let numberOfEvents):
159	            return numberOfEvents
160	        }
161	    }
162	    
163	    var selectedPinnedIndex: Int {
164	        switch self {
165	        case .loaded(let state):
166	            return state.selectedPinnedIndex
167	        case .loading(let numbersOfEvents):
168	            // We always want the index to be the last one when loading, since is the default one.
169	            return numbersOfEvents - 1
170	        }
171	    }
172	    
173	    var displayedMessage: AttributedString {
174	        switch self {
175	        case .loading:
176	            return AttributedString(L10n.screenRoomPinnedBannerLoadingDescription)
177	        case .loaded(let state):
178	            return state.selectedPinnedContent
179	        }
180	    }
181	    
182	    var bannerIndicatorDescription: AttributedString {
183	        let index = selectedPinnedIndex + 1
184	        let boldPlaceholder = "{bold}"
185	        var finalString = AttributedString(L10n.screenRoomPinnedBannerIndicatorDescription(boldPlaceholder))
186	        var boldString = AttributedString(L10n.screenRoomPinnedBannerIndicator(index, count))
187	        boldString.bold()
188	        finalString.replace(boldPlaceholder, with: boldString)
189	        return finalString
190	    }
191	    
192	    mutating func previousPin() {
193	        switch self {
194	        case .loaded(var state):
195	            state.previousPin()
196	            self = .loaded(state: state)
197	        default:
198	            break
199	        }
200	    }
201	    
202	    mutating func setPinnedEventContents(_ pinnedEventContents: OrderedDictionary<String, AttributedString>) {
203	        switch self {
204	        case .loading:
205	            // The default selected event should always be the last one.
206	            self = .loaded(state: .init(pinnedEventContents: pinnedEventContents, selectedPinnedEventID: pinnedEventContents.keys.last))
207	        case .loaded(var state):
208	            state.pinnedEventContents = pinnedEventContents
209	            self = .loaded(state: state)
210	        }
211	    }
212	    
213	    /// Note that if we are setting this value, this is definitely sent from the pinned events timeline
214	    /// so we can assume that the pinned events timeline is already loaded and we only need to set the
215	    /// selection for the loaded state
216	    mutating func setSelectedPinnedEventID(_ eventID: String) {
217	        switch self {
218	        case .loaded(var state):
219	            state.selectedPinnedEventID = eventID
220	            self = .loaded(state: state)
221	        case .loading:
222	            break
223	        }
224	    }
225	}
