227	@MainActor
228	struct PinnedEventsState: Equatable {
229	    var pinnedEventContents: OrderedDictionary<String, AttributedString> = [:] {
230	        didSet {
231	            if selectedPinnedEventID == nil, !pinnedEventContents.keys.isEmpty {
232	                // The default selected event should always be the last one.
233	                selectedPinnedEventID = pinnedEventContents.keys.last
234	            } else if pinnedEventContents.isEmpty {
235	                selectedPinnedEventID = nil
236	            } else if let selectedPinnedEventID, !pinnedEventContents.keys.set.contains(selectedPinnedEventID) {
237	                self.selectedPinnedEventID = pinnedEventContents.keys.last
238	            }
239	        }
240	    }
241	    
242	    var selectedPinnedEventID: String?
243	    
244	    var selectedPinnedIndex: Int {
245	        let defaultValue = pinnedEventContents.isEmpty ? 0 : pinnedEventContents.count - 1
246	        guard let selectedPinnedEventID else {
247	            return defaultValue
248	        }
249	        return pinnedEventContents.keys.firstIndex(of: selectedPinnedEventID) ?? defaultValue
250	    }
251	    
252	    var selectedPinnedContent: AttributedString {
253	        var content = AttributedString(" ")
254	        if let selectedPinnedEventID,
255	           let pinnedEventContent = pinnedEventContents[selectedPinnedEventID] {
256	            content = pinnedEventContent
257	        }
258	        content.font = .compound.bodyMD
259	        content.link = nil
260	        return content
261	    }
262	    
263	    mutating func previousPin() {
264	        guard !pinnedEventContents.isEmpty else {
265	            return
266	        }
267	        let currentIndex = selectedPinnedIndex
268	        let nextIndex = currentIndex - 1
269	        if nextIndex == -1 {
270	            selectedPinnedEventID = pinnedEventContents.keys.last
271	        } else {
272	            selectedPinnedEventID = pinnedEventContents.keys[nextIndex % pinnedEventContents.count]
273	        }
274	    }
275	}
